// dryRun vem do aceite pelo WhatsApp com &ensaio=1. Nos demais gatilhos
// (5h e manual) nao existe e o valor cai para false.
const entrada = $input.first()?.json || {}
return [{ json: { alvo: 'producao', dryRun: entrada.dryRun === true } }]

// O ensaio das 3h30 nao toca em producao: builda a arvore aprovada numa
// stack descartavel, com um clone do banco, e grava o selo que o run das
// 5h consome. Se ele reprovar, o deploy nem comeca.
return [{ json: { alvo: 'ensaio', dryRun: false } }]

// Transforma o relatorio JSON do agente numa mensagem de WhatsApp.
//
// Quem le isto as 8h da manha precisa decidir em 5 segundos se precisa agir.
// Por isso a primeira linha ja diz o desfecho, e o resto e detalhe.

const DESTINO = '5511947250110'
// $input.first(), nao $json: no modo padrao do no Code (uma vez para todos os
// itens) o $json nao existe. Mesmo padrao do DailyTasks.
const bruto = $input.first()?.json || {}

// A rota /execucao/<id> devolve um envelope { pronto, relatorio, ... }; um
// agente que recusou o pedido devolve o corpo cru. Aceita os dois.
const r = bruto.relatorio || bruto
const ehEnsaio = (bruto.alvo || r.alvo) === 'ensaio'

const agora = new Date().toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit',
})

const linhas = ['*Lidimus ' + (ehEnsaio ? 'Ensaio' : 'Update') + ' - ' + agora + '*']

// O laco de polling desistiu de esperar: passou de 45 min e a execucao
// continua. Nao e falha - e aviso de que o desfecho vem depois.
if (bruto.pronto === false) {
  linhas.push('', '⏳ ' + (ehEnsaio ? 'Ensaio' : 'Deploy') + ' ainda rodando depois de 45 min.')
  linhas.push('', 'Comecou as ' + new Date(bruto.iniciadoEm).toLocaleString('pt-BR', {
    timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit',
  }) + '. O desfecho fica em .lidimus/historico/' + bruto.id + '.json')
  return [{ json: { number: DESTINO, texto: linhas.join('\n') } }]
}

// Sem campo `resultado` o agente nao respondeu: maquina desligada, agente fora
// do ar, ou o wget morreu no meio. A producao nao foi tocada.
if (!r.resultado) {
  linhas.push('', '🚨 O agente do host nao respondeu.', '')
  linhas.push('A producao NAO foi tocada.')
  linhas.push('Confira se o `pnpm update:agente` esta rodando na maquina.')
  const detalhe = r.error?.message || r.message || r.motivo
  if (detalhe) linhas.push('', '_' + String(detalhe).slice(0, 300) + '_')
  return [{ json: { number: DESTINO, texto: linhas.join('\n') } }]
}

// O ensaio que PASSA nao manda mensagem.
//
// Ele roda as 3h30; um WhatsApp as 4h da manha todo dia vira ruido que ninguem
// le — mesmo principio do lembrete das 22h, que fica calado quando nao ha o que
// aprovar. E o relatorio das 5h ja diz se a imagem veio do ensaio. Reprovacao,
// essa sim, precisa aparecer: e ela que explica por que o deploy das 5h nao vai
// acontecer.
if (ehEnsaio && ['sucesso', 'sucesso-sem-push', 'nada-a-fazer'].includes(r.resultado)) {
  return []
}

const cabecalhos = {
  'sucesso': '✅ Deploy concluido',
  'sucesso-sem-push': '✅ Deploy no ar, mas NAO publicado no GitHub',
  'nada-a-fazer': '💤 Nada aprovado para subir',
  'abortado': '⛔ Deploy nao aconteceu (producao intacta)',
  'rollback': '↩️ Deploy revertido para a versao anterior',
  'intervencao-manual': '🚨 PRECISA DE INTERVENCAO MANUAL',
  'erro-do-agente': '🚨 Falha no proprio agente',
}

// O ensaio das 3h30 nao mexe em producao: os mesmos desfechos querem dizer
// outra coisa. 'abortado' aqui e boa noticia - achou o problema antes.
const cabecalhosEnsaio = {
  'sucesso': '🎬 Ensaio aprovado - o deploy das 5h esta liberado',
  'sucesso-sem-push': '🎬 Ensaio aprovado',
  'nada-a-fazer': '💤 Nada aprovado para ensaiar',
  'abortado': '🎬 Ensaio REPROVOU - o deploy das 5h NAO vai acontecer',
  'rollback': '🎬 Ensaio REPROVOU no smoke - o deploy das 5h NAO vai acontecer',
  'intervencao-manual': '🎬 Ensaio travou - olhe a maquina antes das 5h',
  'erro-do-agente': '🚨 Falha no proprio agente',
}
linhas.push('', (ehEnsaio ? cabecalhosEnsaio : cabecalhos)[r.resultado] || ('❓ ' + r.resultado))

if (r.motivo) linhas.push('', r.motivo)

if (r.aprovacao?.descricao) {
  // De onde veio o aceite deixa o historico auditavel: aprovar pelo celular e
  // aprovar no teclado tem o mesmo peso, mas nao a mesma trilha.
  const via = r.aprovacao.aprovadoPor === 'whatsapp' ? ' (pelo WhatsApp)' : ''
  linhas.push('', '📋 Aprovado' + via + ': _' + r.aprovacao.descricao + '_')
}

// Nada aprovado quase nunca e decisao — e esquecimento. Listar o que ficou
// parado e oferecer o link de aceite e o que torna este aviso acionavel sem
// precisar chegar na maquina. So aparece quando ha mesmo algo esperando.
if (r.pendencia) {
  const p = r.pendencia
  linhas.push('', '📝 Esperando aprovacao (' + String(p.commit || '').slice(0, 7) + '):')
  if (p.arquivos?.length) {
    linhas.push('   ' + p.arquivos.length + ' arquivo(s) alterado(s)')
    for (const a of p.arquivos.slice(0, 3)) linhas.push('   • ' + a)
    if (p.arquivos.length > 3) linhas.push('   • ...e mais ' + (p.arquivos.length - 3))
  }
  if (p.commitsAFrente) linhas.push('   ' + p.commitsAFrente + ' commit(s) ainda nao publicado(s)')
  if (p.url) {
    linhas.push('', '👉 Aprovar e subir agora:', p.url)
    linhas.push('_o link vale ate ' + p.validoAteTexto + '_')
  }
}

if (r.codigo?.commits?.length) {
  linhas.push('', '📦 Codigo: ' + r.codigo.commits.length + ' commit(s)')
  for (const c of r.codigo.commits.slice(0, 5)) linhas.push('   • ' + c)
  if (r.codigo.commits.length > 5) linhas.push('   • ...e mais ' + (r.codigo.commits.length - 5))
}

// So fala de migrations e n8n se a fase correspondente rodou de verdade.
// Um abort no preflight nao autoriza dizer 'nenhuma pendente'.
if (r.migrations?.verificado) {
  const p = r.migrations.pendentes || []
  if (!p.length) linhas.push('', '🗄️ Migrations: nenhuma pendente')
  else if (r.migrations.aplicadas) linhas.push('', '🗄️ Migrations aplicadas: ' + p.join(', '))
  else linhas.push('', '🗄️ Migrations pendentes NAO aplicadas: ' + p.join(', '))
}

if (r.n8n?.verificado) {
  const d = r.n8n.divergentes || []
  if (d.length) {
    linhas.push('', '🔄 n8n: ' + d.length + ' workflow(s) divergente(s) - revisar')
    for (const w of d.slice(0, 5)) {
      const nos = [...(w.nos?.alterados || []), ...(w.nos?.acrescentados || [])].slice(0, 3)
      linhas.push('   • ' + w.arquivo + (nos.length ? ' (' + nos.join(', ') + ')' : ''))
    }
  } else {
    linhas.push('', '🔄 n8n: em sincronia com o repositorio')
  }
  for (const e of (r.n8n.erros || [])) linhas.push('   ! ' + e)
}

if (r.smoke?.length) {
  const passaram = r.smoke.filter((t) => t.ok).length
  linhas.push('', '🧪 Smoke: ' + passaram + '/' + r.smoke.length + ' passaram')
  for (const t of r.smoke.filter((t) => !t.ok)) linhas.push('   ✗ ' + t.nome)
}

if (r.deploy?.downtimeSegundos != null) {
  linhas.push('', '⏱️ Indisponibilidade: ' + r.deploy.downtimeSegundos + 's')
}

if (r.github?.empurrado) {
  linhas.push('🐙 GitHub: ' + (r.github.commit || 'push') + ' publicado')
} else if (r.github?.pendencia) {
  // O deploy subiu; o que ficou para tras foi a publicacao. Pendencia de
  // push o run seguinte retenta sozinho; de commit (arquivo barrado pela
  // peneira) precisa de gente.
  linhas.push('', '🐙 GitHub: NAO publicado (' + r.github.pendencia.tipo + ')')
  linhas.push('   ' + String(r.github.pendencia.motivo || '').slice(0, 200))
}

// Quando a imagem vem do ensaio, o deploy das 5h nao buildou nada: sao
// segundos de recriacao em vez de meia hora de build no caminho critico.
if (r.deploy?.origemDaImagem === 'ensaio') {
  linhas.push('🎬 Imagem promovida do ensaio (sem rebuildar)')
}

if (r.disco?.livreGbDepois != null) {
  linhas.push('💾 Disco: ' + r.disco.livreGbDepois + ' GB livres')
}

// O caminho do dump so aparece quando ele importa: alguem vai precisar dele.
if (r.resultado === 'intervencao-manual' && r.deploy?.dump) {
  linhas.push('', '💾 Backup do banco: ' + r.deploy.dump)
}

// O ultimo erro costuma ser o proprio motivo, ja impresso la em cima.
const ultimo = r.erros?.length ? String(r.erros[r.erros.length - 1]) : null
if (ultimo && ultimo !== r.motivo && r.resultado !== 'nada-a-fazer') {
  linhas.push('', '⚠️ ' + ultimo.slice(0, 400))
}

return [{ json: { number: DESTINO, texto: linhas.join('\n') } }]
